package com.worksphere.controller; import com.worksphere.dto.profile.*; import com.worksphere.service.EmployerProfileService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/users/me/employer-profile") public class EmployerProfileController {private final EmployerProfileService s;public EmployerProfileController(EmployerProfileService x){s=x;} @GetMapping public EmployerProfileResponse get(Authentication a){return s.get(a);} @PutMapping public EmployerProfileResponse save(Authentication a,@RequestBody EmployerProfileRequest r){return s.save(a,r);} }
